/**
 * Splash screen, generated by the compiler.
 *
 * The deal: the author writes an ANIMATION, nothing else. They point
 * `splash: "./src/splash.hys"` at a module exporting `Splash()`, and the
 * framework handles everything that makes a splash actually work:
 *
 *   - it is in the HTML from the first paint (a React component cannot be: the
 *     bundle has not loaded yet when the first paint happens)
 *   - it covers the viewport until the page is ready, with a ceiling so nothing
 *     can hang
 *   - it leaves by itself, once the author's animation says it is done
 *   - if JS never runs, a CSS-only fail-safe lets the visitor clear it anyway
 *
 * Why this lives in the framework rather than in each project: the hard part is
 * not the animation, it is the four bugs every hand-written splash hits.
 *
 *   1. The wrapper gets the background colour, so elements sliding away reveal
 *      the same colour behind them and nothing appears to happen.
 *   2. A CSS animation on a panel outranks the plain transform meant to release
 *      it, so the panel stays locked until the animation fires. Two "correct"
 *      declarations and one silently wins.
 *   3. translateY(-100%) on a flex:1 panel moves it zero pixels, because the
 *      percentage resolves against its own height, which is already the
 *      container's.
 *   4. If JS is blocked or fails, the panel never leaves and the site is
 *      permanently covered.
 *
 * The generated shell avoids all four by construction, and the author never has
 * to know they existed.
 *
 * The module contract, kept as small as possible:
 *
 *     def Splash(done):
 *         # done() -> the splash leaves. Call it when the animation ends.
 *         # window.hydra.splash.ready() -> same, but waits for fonts and
 *         # first-viewport images first.
 *
 * `done` is passed in, so the author does not have to know how the release is
 * wired. If they never call it, the framework's ceiling takes over.
 */

export const DEFAULT_COLOR = '#cc785c';
export const DEFAULT_FALLBACK_MS = 5000;

const HEX = /^#(?:[0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/i;

/**
 * Normalise the `splash` config key.
 *
 * Accepts either a plain path string or `{ src, color, fallbackMs }`. Returns
 * null when the project does not use a splash. Throws on a value that cannot be
 * honoured -- a splash that silently does not appear is worse than a build error
 * that says why.
 */
export function resolveOptions(raw) {
  if (raw === undefined || raw === null || raw === false) return null;

  let src;
  let color = DEFAULT_COLOR;
  let fallbackMs = DEFAULT_FALLBACK_MS;

  if (typeof raw === 'string') {
    src = raw;
  } else if (typeof raw === 'object') {
    src = raw.src || raw.module;
    if (raw.color !== undefined) color = String(raw.color);
    if (raw.fallbackMs !== undefined) {
      fallbackMs = Number(raw.fallbackMs);
      if (!Number.isFinite(fallbackMs) || fallbackMs < 1000) {
        throw new Error(
          `splash.fallbackMs must be a number >= 1000, got ${JSON.stringify(raw.fallbackMs)}`,
        );
      }
    }
    if (raw.count !== undefined) {
      throw new Error(
        'splash.count is no longer used: the splash is drawn by your module, ' +
          'not generated from a panel count. Export Splash() and build what you want.',
      );
    }
  } else {
    throw new Error(`splash must be a path string or an object, got ${typeof raw}`);
  }

  if (!src || typeof src !== 'string') {
    throw new Error('splash.src is required, e.g. splash: "./src/splash.hys"');
  }
  if (!HEX.test(color)) {
    throw new Error(`splash.color must be a hex colour like #cc785c, got ${JSON.stringify(color)}`);
  }

  return { src, color: color.toLowerCase(), fallbackMs };
}

/**
 * The boot helper, inlined into the page before the bundle.
 *
 * This is the whole mechanism. The waiting is exposed rather than forced: an
 * author's animation usually starts with its own entrance, and blocking the
 * first frame on network requests would make it feel stuck. So `release()` is
 * immediate and `ready()` waits.
 */
export function bootScript(options, nonce = '') {
  const n = nonce ? ` nonce="${nonce}"` : '';
  const lines = [
    `<script data-hydra-splash-boot="1"${n} data-splash-src="${options.chunk || ''}">(function(){`,
    "  var el = document.getElementById('boot-splash');",
    '  if (!el) return;',
    '  var released = false;',
    '  function release() {',
    '    if (released) return;',
    '    released = true;',
    "    el.classList.add('is-ready');",
    "    el.setAttribute('aria-hidden', 'true');",
    '    // Drop it from the page once the exit transition is over, so it can never',
    '    // intercept a click or sit in the accessibility tree.',
    '    setTimeout(function(){ if (el.parentNode) el.parentNode.removeChild(el); }, 1400);',
    '  }',
    '  // Hard ceiling: whatever happens below, the page is never left covered.',
    `  setTimeout(release, ${options.fallbackMs});`,
    '  window.hydra = window.hydra || {};',
    '  // Satu objek, dipakai bersama. Entry splash menambahkan `done` ke objek ini',
    '  // juga -- kalau ia membuat objek baru, `done` memanggil fungsi yang tidak',
    '  // pernah menyentuh elemen shell, dan splash hanya lepas lewat plafon.',
    '  var api = window.hydra.splash || {};',
    '  api.release = release;',
    '  api.done = release;',
    '  window.hydra.splash = api;',
    '  api.released = function(){ return released; };',
    '  api.ready = function(cb){',
    '      var imgs = [], i, done = false;',
    '      function finish(){ if (done) return; done = true; if (cb) cb(); release(); }',
    '      try {',
    '        var vh = window.innerHeight || 800;',
    '        for (i = 0; i < document.images.length; i++) {',
    '          var r = document.images[i].getBoundingClientRect();',
    '          // Only images in the first viewport. A lazy image below the fold has',
    '          // no box yet, and document.images is the wrong list to wait on.',
    '          if (r.top < vh && r.bottom > -200 && r.width > 0) imgs.push(document.images[i]);',
    '        }',
    '      } catch (e) { finish(); return; }',
    '      var pending = 0;',
    '      for (i = 0; i < imgs.length; i++) {',
    '        if (imgs[i].complete && imgs[i].naturalWidth > 0) continue;',
    '        pending++;',
    "        imgs[i].addEventListener('load', function(){ if (--pending <= 0) finish(); }, { once: true });",
    "        imgs[i].addEventListener('error', function(){ if (--pending <= 0) finish(); }, { once: true });",
    '      }',
    '      var fired = false;',
    '      function afterFonts(){',
    '        if (fired) return;',
    '        fired = true;',
    '        if (pending <= 0) setTimeout(finish, 60); else setTimeout(finish, 1500);',
    '      }',
    '      try {',
    '        if (document.fonts && document.fonts.ready) {',
    '          document.fonts.ready.then(afterFonts, afterFonts);',
    '          setTimeout(afterFonts, 2000);',
    '        } else afterFonts();',
    '      } catch (e) { afterFonts(); }',
    '  };',
    '  // Muat chunk animasi. Shell sudah menutupi layar sejak paint pertama, jadi',
    '  // animasi boleh menyusul beberapa milidetik kemudian tanpa terlihat.',
    '  // Dynamic import dipakai supaya proyek tanpa splash tidak membayar apa pun.',
    "  var src = document.currentScript && document.currentScript.getAttribute('data-splash-src');",
    '  if (src) {',
    '    try { import(src).catch(function(){}); } catch (e) {}',
    '  }',
    '})();</script>',
  ];
  return lines.join('\n');
}

/** The root node the author's module renders into. */
export function splashHtml(color) {
  // Penanda HTML, bukan hanya id: pembersih harus bisa membuang blok lama
  // secara utuh, dan regex berdasar id saja gampang meleset pada struktur
  // bersarang -- splash lalu menumpuk dua kali setiap kali disuntik.
  return (
    '<!--hydra-splash:start-->' +
    '<input type="button" id="boot-bail" aria-hidden="true" tabindex="-1" value="" autocomplete="off">' +
    `<div id="boot-splash" aria-hidden="true" style="--splash-color:${color}">` +
    '<div id="boot-splash-mount"></div>' +
    '<div id="boot-splash-host" hidden></div>' +
    '</div>' +
    '<!--hydra-splash:end-->'
  );
}

/** Base styles: only the mechanics. The author owns the look. */
export function splashCss(options, nonce = '') {
  const n = nonce ? ` nonce="${nonce}"` : '';
  const lines = [
    `<style${n} data-hydra-splash="1">`,
    '  /* ---- splash shell (generated by HydraScript) ----',
    '     Kontainer sengaja TIDAK berwarna: kalau ia berwarna, elemen yang bergeser',
    '     pergi hanya memperlihatkan warna yang sama, dan hasilnya blok yang tidak',
    '     pernah hilang. Warna latar ada di #boot-splash-mount, milik animasi. */',
    '  #boot-splash {',
    '    position: fixed; inset: 0; z-index: 9999;',
    '    overflow: hidden; pointer-events: none;',
    '    background: transparent;',
    '    display: flex;',
    '  }',
    '  #boot-splash-mount { flex: 1 1 auto; min-width: 0; position: relative; }',
    '  /* Keadaan keluar: shell geser ke atas. Animasi milik penulis berjalan di',
    '     dalam mount, jadi keduanya tidak berebut properti yang sama. */',
    '  #boot-splash, #boot-splash-mount { transform: translateY(0); }',
    '  #boot-splash.is-ready {',
    '    transform: translateY(-102%);',
    '    transition: transform 700ms cubic-bezier(.53, 0, .14, 1);',
    '  }',
    '',
    '  /* Jaring pengaman tanpa JS. Tak terlihat, menutupi layar, dan baru bisa',
    '     ditekan setelah fallbackMs. Ditekan -> splash pergi, walau bundle gagal',
    '     dimuat sama sekali. :active satu-satunya cara CSS murni mengubah',
    '     keadaan elemen LAIN. */',
    '  #boot-bail {',
    '    position: fixed; inset: 0; z-index: 10000;',
    '    width: 100%; height: 100%; margin: 0; padding: 0; border: 0;',
    '    background: transparent; color: transparent;',
    '    opacity: 0; pointer-events: none; cursor: default;',
    `    animation: boot-arm 1ms linear ${options.fallbackMs}ms forwards;`,
    '  }',
    '  @keyframes boot-arm { to { pointer-events: auto; opacity: .004; } }',
    '  #boot-bail:active ~ #boot-splash {',
    '    transform: translateY(-102%);',
    '    transition: transform 700ms cubic-bezier(.53, 0, .14, 1);',
    '  }',
    '',
    '  @media (prefers-reduced-motion: reduce) {',
    '    #boot-splash { display: none !important; }',
    '    #boot-bail { display: none !important; }',
    '  }',
    '</style>',
  ];
  return lines.join('\n');
}

const STYLE_RE = /<style[^>]*data-hydra-splash[^>]*>[\s\S]*?<\/style>\s*/gi;
const SCRIPT_RE = /<script[^>]*data-hydra-splash-boot[^>]*>[\s\S]*?<\/script>\s*/gi;
const BLOCK_RE = /<!--hydra-splash:start-->[\s\S]*?<!--hydra-splash:end-->/gi;
// Sisa dari versi tanpa penanda, dan elemen lepas yang mungkin tertinggal.
const INPUT_RE = /<input[^>]*id=["']boot-bail["'][^>]*>\s*/gi;
const SHELL_RE = /<div[^>]*id=["']boot-splash["'][^>]*>[\s\S]*?<\/div>\s*<\/div>\s*<\/div>\s*/gi;
const MARKER = 'data-hydra-splash="1"';

/**
 * Insert the splash shell into a page template.
 *
 * Idempotent: running it twice does not stack a second splash. That matters
 * because the SSG path re-reads the source template for every route.
 */
export function injectSplash(html, options, nonce = '') {
  if (!options) return html;
  let out = html
    .replace(STYLE_RE, '')
    .replace(SCRIPT_RE, '')
    .replace(BLOCK_RE, '')
    .replace(INPUT_RE, '')
    .replace(SHELL_RE, '');

  const style = splashCss(options, nonce);
  const boot = bootScript(options, nonce);
  const shell = splashHtml(options.color);

  out = out.includes('</head>') ? out.replace('</head>', `${style}\n</head>`) : style + out;
  out = /<body[^>]*>/i.test(out)
    ? out.replace(/(<body[^>]*>)/i, `$1${shell}`)
    : shell + out;
  out = out.includes('</body>') ? out.replace('</body>', `${boot}\n</body>`) : out + boot;
  return out;
}

/** True when the page already carries a generated splash shell. */
export function hasGeneratedSplash(html) {
  return html.includes(MARKER);
}
